-- Restructure script: Ensure table exists, alter constraints, prevent duplications
-- ===================================================================================

-- 1. Ensure public.drugs table exists
CREATE TABLE IF NOT EXISTS public.drugs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL UNIQUE,
    category TEXT,
    dosage_forms TEXT[],
    therapeutic TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Ensure RLS is disabled on public.drugs
ALTER TABLE public.drugs DISABLE ROW LEVEL SECURITY;

-- 2. Make student_id in topics table nullable if it was not null before
ALTER TABLE public.topics ALTER COLUMN student_id DROP NOT NULL;

-- 3. Ensure defaults are set for all newly optional fields on topics (for historical titles)
ALTER TABLE public.topics ALTER COLUMN drug_name SET DEFAULT '';
ALTER TABLE public.topics ALTER COLUMN dosage_form SET DEFAULT '';
ALTER TABLE public.topics ALTER COLUMN route_of_admin SET DEFAULT '';
ALTER TABLE public.topics ALTER COLUMN excipients SET DEFAULT '';
ALTER TABLE public.topics ALTER COLUMN method_preparation SET DEFAULT '';
ALTER TABLE public.topics ALTER COLUMN novelty SET DEFAULT '';
ALTER TABLE public.topics ALTER COLUMN keywords SET DEFAULT '';

-- 4. Ensure additional helper columns exist in topics table
ALTER TABLE public.topics ADD COLUMN IF NOT EXISTS department_name TEXT DEFAULT '';
ALTER TABLE public.topics ADD COLUMN IF NOT EXISTS score INTEGER DEFAULT 0;
ALTER TABLE public.topics ADD COLUMN IF NOT EXISTS score_breakdown JSONB DEFAULT '{}'::jsonb;

